import{_ as t,o as r,c as a,ai as o}from"./chunks/framework.C33Uq6m-.js";const p=JSON.parse('{"title":"Local AI History","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/history.md","filePath":"en/guide/history.md"}'),i={name:"en/guide/history.md"};function s(n,e,l,d,c,h){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="local-ai-history" tabindex="-1">Local AI History <a class="header-anchor" href="#local-ai-history" aria-label="Permalink to &quot;Local AI History&quot;">​</a></h1><p>LLMxRay automatically records every experiment you run — benchmarks, comparisons, chats, training. Your research archive, queryable and exportable.</p><h2 id="what-gets-recorded" tabindex="-1">What Gets Recorded <a class="header-anchor" href="#what-gets-recorded" aria-label="Permalink to &quot;What Gets Recorded&quot;">​</a></h2><p>Every interaction with a model produces a history entry. The table below shows what data is captured for each type.</p><table tabindex="0"><thead><tr><th>Entry Type</th><th>Data Captured</th></tr></thead><tbody><tr><td>Benchmark</td><td>Suite name, model, questions, answers, accuracy scores, per-category breakdown, duration</td></tr><tr><td>Compare</td><td>Prompt, models compared, outputs, Token Tax, latency, confidence scores</td></tr><tr><td>Language Compare</td><td>Prompt, languages tested, model, outputs per language, quality metrics</td></tr><tr><td>Chat Session</td><td>Full conversation (all turns), model, timestamps, token counts, latency per token</td></tr><tr><td>Training</td><td>Dataset name, model, training parameters, loss curve, epoch count, duration</td></tr><tr><td>Embedding</td><td>Input text, model, vector dimensions, similarity scores</td></tr><tr><td>Tool Workshop</td><td>Tool definitions, test inputs, model responses, execution results</td></tr></tbody></table><p>Entries are timestamped and tagged with the model name automatically.</p><h2 id="finding-your-data" tabindex="-1">Finding Your Data <a class="header-anchor" href="#finding-your-data" aria-label="Permalink to &quot;Finding Your Data&quot;">​</a></h2><p>The History page provides filters to narrow down your archive.</p><ul><li><strong>Type</strong> — Show only benchmarks, chats, comparisons, or any other entry type.</li><li><strong>Model</strong> — Filter by the model used (e.g., <code>llama3</code>, <code>deepseek-r1</code>, <code>phi4</code>).</li><li><strong>Language</strong> — For language comparisons, filter by the languages tested.</li><li><strong>Date range</strong> — Pick a start and end date to focus on a specific period.</li><li><strong>Tags</strong> — Custom tags you have applied to entries for your own organization.</li></ul><p>Filters combine with AND logic — selecting both a model and a type shows only entries matching both criteria.</p><h2 id="trend-analysis" tabindex="-1">Trend Analysis <a class="header-anchor" href="#trend-analysis" aria-label="Permalink to &quot;Trend Analysis&quot;">​</a></h2><p>The History page includes an activity chart that visualizes your experimentation over time.</p><ul><li><strong>Activity over time</strong> — A timeline showing how many experiments you ran per day or week. Spot gaps or bursts in your research.</li><li><strong>Models used</strong> — A breakdown of which models you tested most. Useful for seeing whether you are over-relying on a single model or exploring broadly.</li><li><strong>Patterns to look for:</strong><ul><li>Accuracy improvements across successive benchmark runs on the same model.</li><li>Latency changes after model updates or parameter adjustments.</li><li>Which model consistently wins comparisons for your use case.</li><li>Training loss curves flattening — a sign that more epochs will not help.</li></ul></li></ul><h2 id="exporting" tabindex="-1">Exporting <a class="header-anchor" href="#exporting" aria-label="Permalink to &quot;Exporting&quot;">​</a></h2><p>History entries can be exported in two formats.</p><ul><li><strong>JSON</strong> — Exports all entries with full structured data. Includes every field: timestamps, model names, prompts, outputs, scores, parameters, and tags. Use for scripting, backup, or reimporting.</li><li><strong>CSV</strong> — Exports the currently filtered view as flat tabular data. Columns include entry type, model, date, summary metrics (accuracy, latency, token count), and tags. Open in Excel, Google Sheets, or pandas.</li></ul><p>To export:</p><ol><li>Apply filters if you want a subset (or leave unfiltered for everything).</li><li>Click the <strong>Export</strong> button.</li><li>Choose JSON or CSV — the file downloads immediately.</li></ol><h2 id="managing-storage" tabindex="-1">Managing Storage <a class="header-anchor" href="#managing-storage" aria-label="Permalink to &quot;Managing Storage&quot;">​</a></h2><p>History is stored in IndexedDB in your browser. It costs nothing and requires no server.</p><ul><li><strong>Retention settings</strong> — Configure how long entries are kept. Options range from 30 days to unlimited. Older entries beyond the retention window are pruned automatically.</li><li><strong>Clearing history</strong> — Use the <strong>Clear History</strong> action to delete all entries, or delete individual entries from the list. This action is irreversible.</li><li><strong>Size estimates</strong> — A typical benchmark entry is 2-5 KB. A full chat session is 5-50 KB depending on length. Thousands of entries fit comfortably within browser storage limits (typically 50 MB+).</li></ul><h2 id="privacy" tabindex="-1">Privacy <a class="header-anchor" href="#privacy" aria-label="Permalink to &quot;Privacy&quot;">​</a></h2><blockquote><p>All history data is stored locally in your browser&#39;s IndexedDB. Nothing is sent to any cloud service. History entries are kept in their own data store, separate from the original benchmark results, chat sessions, and training data. Clearing history does not affect your other data stores.</p></blockquote>',23)])])}const g=t(i,[["render",s]]);export{p as __pageData,g as default};
